from ta_emss.utilities.ex_terminator_rpc.err_transport import ErrRemoteEndpointDisconnected


class RpcCall():
    """Object responsible for calling json-rpc method with error handling and logging"""
    def __init__(self, rpc_socket, logger):
        """Initialization"""
        self.rpc_socket = rpc_socket
        self.logger = logger

    def call(self, data, log_msg='Procedure'):
        """Wraped JsonRpcClient call method with exception handling and logging"""
        try:
            self.logger.info('{} started'.format(log_msg))
            response = self.rpc_socket.call(data)
        except ErrRemoteEndpointDisconnected:
            raise ErrRemoteEndpointDisconnected("JSON_RPC server has crashed while processing the request")
        else:
            self.logger.info('{} succeeded'.format(log_msg))
            return response
